with valid as (select id, product_name, category, brand, price, cost, stock_qty, launch_date, supplier_id, size(tags) as tags_count, coalesce(brand, 'NONE') as brand_clean from products where supplier_id is not null) select id, product_name, category, brand, stock_qty, launch_date, tags_count, brand_clean, max(tags_count) over (partition by supplier_id) as supplier_id_max_tags_count, first_value(brand) ignore nulls over (partition by category order by tags_count, id rows between unbounded preceding and current row) as first_known_brand, row_number() over (partition by category order by launch_date, id) as event_seq from valid;
